package grafana

import (
	"encoding/json"
	"time"
)

// NullableTime represents a time that can be null or empty in JSON
type NullableTime struct {
	Time  time.Time
	Valid bool
}

// UnmarshalJSON implements custom JSON unmarshaling for NullableTime
func (nt *NullableTime) UnmarshalJSON(data []byte) error {
	// Handle null
	if string(data) == "null" {
		nt.Valid = false
		return nil
	}

	// Try to unmarshal as string (Grafana API returns timestamps as strings)
	var s string
	if err := json.Unmarshal(data, &s); err != nil {
		nt.Valid = false
		return err
	}

	// Handle empty string
	if s == "" {
		nt.Valid = false
		return nil
	}

	// Parse the time string (RFC3339Nano format: 2020-05-19T12:37:01.430444Z)
	t, err := time.Parse(time.RFC3339Nano, s)
	if err != nil {
		// Try RFC3339 without nanoseconds
		t, err = time.Parse(time.RFC3339, s)
		if err != nil {
			nt.Valid = false
			return err
		}
	}

	nt.Time = t
	nt.Valid = true
	return nil
}

// MarshalJSON implements custom JSON marshaling for NullableTime
func (nt NullableTime) MarshalJSON() ([]byte, error) {
	if !nt.Valid {
		return []byte("null"), nil
	}
	return json.Marshal(nt.Time)
}

// User represents a Grafana IRM user
type User struct {
	ID        string `json:"id,omitempty"`
	GrafanaID int    `json:"grafana_id,omitempty"`
	Email     string `json:"email,omitempty"`
	Username  string `json:"username,omitempty"`
}

// AlertGroupResponse represents the response from Grafana IRM alert groups endpoint
type AlertGroupResponse struct {
	Count             int          `json:"count,omitempty"`
	Next              interface{}  `json:"next,omitempty"`
	Previous          interface{}  `json:"previous,omitempty"`
	Results           []AlertGroup `json:"results,omitempty"`
	PageSize          int          `json:"page_size,omitempty"`
	PageLength        int          `json:"page_length,omitempty"`
	CurrentPageNumber int          `json:"current_page_number,omitempty"`
	TotalPages        int          `json:"total_pages,omitempty"`
}

// AlertGroup represents a group of related alerts in Grafana IRM
type AlertGroup struct {
	ID             string        `json:"id,omitempty"`
	IntegrationID  string        `json:"integration_id,omitempty"`
	TeamID         string        `json:"team_id,omitempty"`
	RouteID        string        `json:"route_id,omitempty"`
	AlertsCount    int           `json:"alerts_count,omitempty"`
	State          string        `json:"state,omitempty"`
	CreatedAt      NullableTime  `json:"created_at,omitempty"`
	ResolvedAt     NullableTime  `json:"resolved_at,omitempty"`
	ResolvedBy     string        `json:"resolved_by,omitempty"`
	AcknowledgedAt NullableTime  `json:"acknowledged_at,omitempty"`
	AcknowledgedBy string        `json:"acknowledged_by,omitempty"`
	Labels         []interface{} `json:"labels,omitempty"`
	Title          string        `json:"title,omitempty"`
	Permalinks     Permalinks    `json:"permalinks,omitempty"`
	SilencedAt     NullableTime  `json:"silenced_at,omitempty"`
	SilencedBy     string        `json:"silenced_by,omitempty"`
	LastAlert      LastAlert     `json:"last_alert,omitempty"`
}



// Permalinks contains various URLs to access the alert group
type Permalinks struct {
	Slack    interface{} `json:"slack,omitempty"`
	SlackApp interface{} `json:"slack_app,omitempty"`
	Telegram interface{} `json:"telegram,omitempty"`
	Web      string      `json:"web,omitempty"`
}

// LastAlert contains details of the most recent alert in the group
type LastAlert struct {
	ID           string       `json:"id,omitempty"`
	AlertGroupID string       `json:"alert_group_id,omitempty"`
	CreatedAt    NullableTime `json:"created_at,omitempty"`
	Payload      Payload      `json:"payload,omitempty"`
}

// Payload contains the full alert payload from Alertmanager
type Payload struct {
	Alerts            []Alert           `json:"alerts,omitempty"`
	Status            string            `json:"status,omitempty"`
	Version           string            `json:"version,omitempty"`
	GroupKey          string            `json:"groupKey,omitempty"`
	Receiver          string            `json:"receiver,omitempty"`
	NumFiring         int               `json:"numFiring,omitempty"`
	ExternalURL       string            `json:"externalURL,omitempty"`
	GroupLabels       GroupLabels       `json:"groupLabels,omitempty"`
	NumResolved       int               `json:"numResolved,omitempty"`
	CommonLabels      CommonLabels      `json:"commonLabels,omitempty"`
	TruncatedAlerts   int               `json:"truncatedAlerts,omitempty"`
	CommonAnnotations CommonAnnotations `json:"commonAnnotations,omitempty"`
}

// Alert represents a single alert within a group
type Alert struct {
	EndsAt       NullableTime `json:"endsAt,omitempty"`
	Labels       Labels       `json:"labels,omitempty"`
	Status       string       `json:"status,omitempty"`
	StartsAt     NullableTime `json:"startsAt,omitempty"`
	Annotations  Annotations  `json:"annotations,omitempty"`
	Fingerprint  string       `json:"fingerprint,omitempty"`
	GeneratorURL string       `json:"generatorURL,omitempty"`
}

// Labels contains alert labels
type Labels struct {
	Cluster         string `json:"cluster,omitempty"`
	Severity        string `json:"severity,omitempty"`
	Alertname       string `json:"alertname,omitempty"`
	Component       string `json:"component,omitempty"`
	ClusterProvider string `json:"cluster_provider,omitempty"`
}

// Annotations contains alert annotations
type Annotations struct {
	SLO         string `json:"slo,omitempty"`
	Runbook     string `json:"runbook,omitempty"`
	Summary     string `json:"summary,omitempty"`
	Urgency     string `json:"urgency,omitempty"`
	Description string `json:"description,omitempty"`
}

// GroupLabels contains labels that group alerts together
type GroupLabels struct {
	Cluster   string `json:"cluster,omitempty"`
	Alertname string `json:"alertname,omitempty"`
	Component string `json:"component,omitempty"`
}

// CommonLabels contains labels common to all alerts in the group
type CommonLabels struct {
	Cluster         string `json:"cluster,omitempty"`
	Severity        string `json:"severity,omitempty"`
	Alertname       string `json:"alertname,omitempty"`
	Component       string `json:"component,omitempty"`
	ClusterProvider string `json:"cluster_provider,omitempty"`
}

// CommonAnnotations contains annotations common to all alerts in the group
type CommonAnnotations struct {
	SLO         string `json:"slo,omitempty"`
	Runbook     string `json:"runbook,omitempty"`
	Summary     string `json:"summary,omitempty"`
	Urgency     string `json:"urgency,omitempty"`
	Description string `json:"description,omitempty"`
}

package sync

import (
	"context"
	"log"

	"github.com/gabrielpetry/alertmanager-alert-sync/internal/alertmanager"
	"github.com/gabrielpetry/alertmanager-alert-sync/internal/grafana"
	"github.com/gabrielpetry/alertmanager-alert-sync/internal/metrics"
	"github.com/prometheus/alertmanager/api/v2/models"
)

// Reconciler handles the synchronization between Alertmanager and Grafana IRM
type Reconciler struct {
	amClient      *alertmanager.Client
	grafanaClient *grafana.Client
	metrics       *metrics.Exporter
}

// NewReconciler creates a new Reconciler instance
func NewReconciler(amClient *alertmanager.Client, grafanaClient *grafana.Client, metricsExporter *metrics.Exporter) *Reconciler {
	return &Reconciler{
		amClient:      amClient,
		grafanaClient: grafanaClient,
		metrics:       metricsExporter,
	}
}

// InconsistentAlert represents an alert that exists in Alertmanager but not in Grafana IRM
type InconsistentAlert struct {
	Alert               *models.GettableAlert
	GrafanaAlertGroupID string
	Reason              string
	Fingerprint         string
	Alertname           string
}

// ResolveInconsistency handles the resolution of an inconsistent alert
// This function should be called for each alert that needs to be resolved in IRM
func (r *Reconciler) ResolveInconsistency(ctx context.Context, alert InconsistentAlert) error {
	log.Printf("Resolving inconsistency for alert: %s (fingerprint: %s)",
		alert.Alertname, alert.Fingerprint)
	log.Printf("Reason: %s", alert.Reason)

	// Call Grafana API to resolve the alert
	err := r.grafanaClient.ResolveAlertGroup(alert.GrafanaAlertGroupID)
	if err != nil {
		return err
	}

	log.Printf("Successfully resolved alert %s in Grafana IRM", alert.Alertname)

	return nil
}

// ReconcileAndResolveOptimized performs a full reconciliation cycle with optimized data fetching
// It fetches data from Alertmanager and Grafana once, then processes it in parallel goroutines
func (r *Reconciler) ReconcileAndResolveOptimized(ctx context.Context) error {
	// Record reconciliation start and get completion function
	done := r.metrics.RecordReconciliationStart()
	defer done()

	log.Println("Starting optimized reconciliation with parallel operations...")

	// Fetch data from both sources once
	type fetchResult struct {
		alerts             []*models.GettableAlert
		grafanaAlertGroups []grafana.AlertGroup
		err                error
	}

	alertsChan := make(chan fetchResult, 1)
	grafanaChan := make(chan fetchResult, 1)

	// Fetch Alertmanager alerts in parallel
	go func() {
		alerts, err := r.amClient.GetAllAlerts(ctx)
		alertsChan <- fetchResult{alerts: alerts, err: err}
	}()

	// Fetch Grafana alert groups in parallel
	go func() {
		groups, err := r.grafanaClient.GetAllAlertGroups()
		grafanaChan <- fetchResult{grafanaAlertGroups: groups, err: err}
	}()

	// Wait for both fetches to complete
	alertsResult := <-alertsChan
	grafanaResult := <-grafanaChan

	if alertsResult.err != nil {
		r.metrics.RecordReconciliationFailure()
		return alertsResult.err
	}
	if grafanaResult.err != nil {
		r.metrics.RecordReconciliationFailure()
		return grafanaResult.err
	}

	log.Printf("Fetched %d alerts from Alertmanager", len(alertsResult.alerts))
	log.Printf("Fetched %d alert groups from Grafana", len(grafanaResult.grafanaAlertGroups))

	// Now perform two operations in parallel using the same data
	type operationResult struct {
		name  string
		err   error
		stats map[string]int
	}

	resultsChan := make(chan operationResult, 2)

	// Goroutine 1: Export metrics with Grafana data
	go func() {
		log.Println("Starting metrics export with Grafana data...")
		err := r.metrics.ExportAlertsWithGrafana(ctx, alertsResult.alerts, grafanaResult.grafanaAlertGroups, r.grafanaClient, r.amClient)
		if err != nil {
			log.Printf("Metrics export failed: %v", err)
			r.metrics.RecordAlertExportFailure()
		} else {
			log.Println("Metrics export completed successfully")
		}
		resultsChan <- operationResult{name: "metrics_export", err: err}
	}()

	// Goroutine 2: Reconcile and resolve inconsistencies
	go func() {
		log.Println("Starting silence reconciliation...")

		// Filter for silenced firing alerts
		silencedAlerts := make([]*models.GettableAlert, 0)
		for _, alert := range alertsResult.alerts {
			if alert.Status != nil &&
				*alert.Status.State == "suppressed" &&
				len(alert.Status.SilencedBy) > 0 {
				silencedAlerts = append(silencedAlerts, alert)
			}
		}

		log.Printf("Found %d silenced firing alerts", len(silencedAlerts))

		// Build a map of alert fingerprints from Grafana IRM for quick lookup
		grafanaFingerprints := make(map[string]string)
		for _, group := range grafanaResult.grafanaAlertGroups {
			if group.State != "resolved" {
				for _, alert := range group.LastAlert.Payload.Alerts {
					if alert.Fingerprint != "" {
						grafanaFingerprints[alert.Fingerprint] = group.ID
					}
				}
			}
		}

		// Find inconsistencies
		var inconsistencies []InconsistentAlert
		for _, alert := range silencedAlerts {
			fingerprint := alert.Fingerprint
			alertname := alert.Labels["alertname"]

			if _, exists := grafanaFingerprints[*fingerprint]; exists {
				inconsistencies = append(inconsistencies, InconsistentAlert{
					Alert:               alert,
					Reason:              "Alert is silenced in Alertmanager but still firing in Grafana IRM",
					Fingerprint:         *fingerprint,
					Alertname:           alertname,
					GrafanaAlertGroupID: grafanaFingerprints[*fingerprint],
				})
			}
		}

		log.Printf("Found %d inconsistent alerts", len(inconsistencies))

		// Resolve inconsistencies
		resolvedCount := 0
		for _, inconsistency := range inconsistencies {
			if err := r.ResolveInconsistency(ctx, inconsistency); err != nil {
				log.Printf("Failed to resolve inconsistency for alert %s: %v",
					inconsistency.Alertname, err)
				r.metrics.RecordInconsistencyFailedResolve()
			} else {
				r.metrics.RecordInconsistencyResolved()
				resolvedCount++
			}
		}

		stats := map[string]int{
			"inconsistencies": len(inconsistencies),
			"resolved":        resolvedCount,
		}

		resultsChan <- operationResult{name: "silence_reconciliation", stats: stats}
	}()

	// Wait for both operations to complete
	var metricsErr error
	var reconcileStats map[string]int

	for i := 0; i < 2; i++ {
		result := <-resultsChan
		if result.name == "metrics_export" {
			metricsErr = result.err
		} else if result.name == "silence_reconciliation" {
			reconcileStats = result.stats
		}
	}

	// Record reconciliation success
	if metricsErr == nil && reconcileStats != nil {
		r.metrics.RecordReconciliationSuccess(
			reconcileStats["inconsistencies"],
			reconcileStats["resolved"],
		)
		log.Println("Optimized reconciliation completed successfully")
		return nil
	}

	if metricsErr != nil {
		r.metrics.RecordReconciliationFailure()
		return metricsErr
	}

	return nil
}

package grafana

import (
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"sync"
	"time"
)

const (
	alertGroupsEndpoint   = "/api/v1/alert_groups"
	resolveAlertEndpoint  = "/api/v1/alert_groups/%s/resolve"
	unsilenceAlertEndpoint = "/api/v1/alert_groups/%s/unsilence"
	userEndpoint          = "/api/v1/users/%s"
)

// Client wraps the Grafana IRM API client
type Client struct {
	baseURL    string
	apiToken   string
	httpClient *http.Client
	userCache  map[string]*User
	cacheMutex sync.RWMutex
}

// NewClient creates a new Grafana IRM client
// It reads GRAFANA_IRM_URL and GRAFANA_IRM_TOKEN from environment variables
func NewClient() (*Client, error) {
	baseURL := os.Getenv("GRAFANA_IRM_URL")
	if baseURL == "" {
		return nil, fmt.Errorf("GRAFANA_IRM_URL environment variable not set")
	}

	apiToken := os.Getenv("GRAFANA_IRM_TOKEN")
	if apiToken == "" {
		return nil, fmt.Errorf("GRAFANA_IRM_TOKEN environment variable not set")
	}

	return &Client{
		baseURL:  baseURL,
		apiToken: apiToken,
		httpClient: &http.Client{
			Timeout: 10 * time.Second,
		},
		userCache: make(map[string]*User),
	}, nil
}

// GetAllAlertGroups retrieves all alert groups from Grafana IRM (firing, resolved, etc.)
func (c *Client) GetAllAlertGroups() ([]AlertGroup, error) {
	url := fmt.Sprintf("%s%s", c.baseURL, alertGroupsEndpoint)
	log.Printf("Fetching all alert groups from URL: %s", url)

	req, err := http.NewRequest("GET", url, nil)
	if err != nil {
		return nil, fmt.Errorf("creating request: %w", err)
	}

	req.Header.Set("Authorization", c.apiToken)
	req.Header.Set("Content-Type", "application/json")

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("executing request: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(resp.Body)
		return nil, fmt.Errorf("API returned status %d: %s", resp.StatusCode, string(body))
	}

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("reading response: %w", err)
	}

	var response AlertGroupResponse
	if err := json.Unmarshal(body, &response); err != nil {
		return nil, fmt.Errorf("parsing response: %w", err)
	}

	return response.Results, nil
}

func (c *Client) ResolveAlertGroup(alertGroupID string) error {
	url := fmt.Sprintf("%s%s", c.baseURL, fmt.Sprintf(resolveAlertEndpoint, alertGroupID))
	log.Printf("Resolving alert group at URL: %s", url)

	req, err := http.NewRequest("POST", url, nil)
	if err != nil {
		return fmt.Errorf("creating request: %w", err)
	}

	req.Header.Set("Authorization", c.apiToken)
	req.Header.Set("Content-Type", "application/json")

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return fmt.Errorf("executing request: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(resp.Body)
		return fmt.Errorf("API returned status %d: %s", resp.StatusCode, string(body))
	}

	log.Printf("Successfully resolved alert group: %s", alertGroupID)
	return nil
}

// UnsilenceAlertGroup unsilences an alert group in Grafana IRM
func (c *Client) UnsilenceAlertGroup(alertGroupID string) error {
	url := fmt.Sprintf("%s%s", c.baseURL, fmt.Sprintf(unsilenceAlertEndpoint, alertGroupID))
	log.Printf("Unsilencing alert group at URL: %s", url)

	req, err := http.NewRequest("POST", url, nil)
	if err != nil {
		return fmt.Errorf("creating request: %w", err)
	}

	req.Header.Set("Authorization", c.apiToken)
	req.Header.Set("Content-Type", "application/json")

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return fmt.Errorf("executing request: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(resp.Body)
		return fmt.Errorf("API returned status %d: %s", resp.StatusCode, string(body))
	}

	log.Printf("Successfully unsilenced alert group: %s", alertGroupID)
	return nil
}

// GetUser retrieves user information by user ID with caching
func (c *Client) GetUser(userID string) (*User, error) {
	if userID == "" {
		return nil, nil
	}

	// Check cache first (read lock)
	c.cacheMutex.RLock()
	if user, exists := c.userCache[userID]; exists {
		c.cacheMutex.RUnlock()
		return user, nil
	}
	c.cacheMutex.RUnlock()

	// User not in cache, fetch from API
	url := fmt.Sprintf("%s%s", c.baseURL, fmt.Sprintf(userEndpoint, userID))
	log.Printf("Fetching user from URL: %s", url)

	req, err := http.NewRequest("GET", url, nil)
	if err != nil {
		return nil, fmt.Errorf("creating request: %w", err)
	}

	req.Header.Set("Authorization", c.apiToken)
	req.Header.Set("Content-Type", "application/json")

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("executing request: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(resp.Body)
		return nil, fmt.Errorf("API returned status %d: %s", resp.StatusCode, string(body))
	}

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("reading response: %w", err)
	}

	var user User
	if err := json.Unmarshal(body, &user); err != nil {
		return nil, fmt.Errorf("parsing response: %w", err)
	}

	// Store in cache (write lock)
	c.cacheMutex.Lock()
	c.userCache[userID] = &user
	c.cacheMutex.Unlock()

	log.Printf("Cached user %s (email: %s)", userID, user.Email)
	return &user, nil
}

// GetUserEmail retrieves only the email for a user ID (with caching)
func (c *Client) GetUserEmail(userID string) string {
	user, err := c.GetUser(userID)
	if err != nil {
		log.Printf("Failed to fetch user %s: %v", userID, err)
		return ""
	}
	if user == nil {
		return ""
	}
	return user.Email
}

package server

import (
	"fmt"
	"net/http"

	"github.com/gabrielpetry/alertmanager-alert-sync/internal/alertmanager"
	"github.com/gabrielpetry/alertmanager-alert-sync/internal/grafana"
	"github.com/gabrielpetry/alertmanager-alert-sync/internal/metrics"
	"github.com/gabrielpetry/alertmanager-alert-sync/internal/sync"
	"github.com/prometheus/client_golang/prometheus/promhttp"
)

// Server holds all dependencies for HTTP handlers
type Server struct {
	amClient      *alertmanager.Client
	grafanaClient *grafana.Client
	exporter      *metrics.Exporter
	reconciler    *sync.Reconciler
}

// NewServer creates a new server with all dependencies
func NewServer(
	amClient *alertmanager.Client,
	grafanaClient *grafana.Client,
	exporter *metrics.Exporter,
	reconciler *sync.Reconciler,
) *Server {
	return &Server{
		amClient:      amClient,
		grafanaClient: grafanaClient,
		exporter:      exporter,
		reconciler:    reconciler,
	}
}

// MetricsHandler serves Prometheus metrics for reconciliation
func (s *Server) MetricsHandler(w http.ResponseWriter, r *http.Request) {
	promhttp.Handler().ServeHTTP(w, r)
}

// HealthzHandler provides a Kubernetes-style liveness probe endpoint
// Returns 200 OK if the service is running and ready to accept traffic
func (s *Server) HealthzHandler(w http.ResponseWriter, r *http.Request) {
	// Check if reconciler is initialized (requires Grafana client)
	if s.reconciler == nil {
		http.Error(w, "Not ready: reconciler not initialized", http.StatusServiceUnavailable)
		return
	}

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "OK\n")
}

// ReadyzHandler provides a Kubernetes-style readiness probe endpoint
// Returns 200 OK if the service is ready to accept traffic
func (s *Server) ReadyzHandler(w http.ResponseWriter, r *http.Request) {
	// Check if reconciler is initialized (requires Grafana client)
	if s.reconciler == nil {
		http.Error(w, "Not ready: reconciler not initialized", http.StatusServiceUnavailable)
		return
	}

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "Ready\n")
}

package server

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
