	"github.com/go-openapi/strfmt"
	"github.com/prometheus/alertmanager/api/v2/models"
)

// WebhookEvent represents the incoming webhook payload from Grafana IRM
type WebhookEvent struct {
	Event struct {
		Type  string `json:"type"`
		Time  string `json:"time"`
		Until string `json:"until"`
	} `json:"event"`
	User struct {
		ID       string `json:"id"`
		Username string `json:"username"`
		Email    string `json:"email"`
	} `json:"user"`
	AlertGroup struct {
		ID             string                 `json:"id"`
		IntegrationID  string                 `json:"integration_id"`
		TeamID         string                 `json:"team_id"`
		RouteID        string                 `json:"route_id"`
		AlertsCount    int                    `json:"alerts_count"`
		State          string                 `json:"state"`
		CreatedAt      string                 `json:"created_at"`
		ResolvedAt     *string                `json:"resolved_at"`
		ResolvedBy     *string                `json:"resolved_by"`
		AcknowledgedAt *string                `json:"acknowledged_at"`
		AcknowledgedBy *string                `json:"acknowledged_by"`
		Labels         map[string]interface{} `json:"labels"`
		Title          string                 `json:"title"`
		Permalinks     struct {
			Slack    *string `json:"slack"`
			SlackApp *string `json:"slack_app"`
			Telegram *string `json:"telegram"`
			Web      string  `json:"web"`
		} `json:"permalinks"`
		SilencedAt string `json:"silenced_at"`
		LastAlert  struct {
			ID           string `json:"id"`
			AlertGroupID string `json:"alert_group_id"`
			CreatedAt    string `json:"created_at"`
			Payload      struct {
				Alerts []struct {
					EndsAt       string            `json:"endsAt"`
					Labels       map[string]string `json:"labels"`
					Status       string            `json:"status"`
					StartsAt     string            `json:"startsAt"`
					Annotations  map[string]string `json:"annotations"`
					Fingerprint  string            `json:"fingerprint"`
					GeneratorURL string            `json:"generatorURL"`
				} `json:"alerts"`
				Status            string            `json:"status"`
				Version           string            `json:"version"`
				GroupKey          string            `json:"groupKey"`
				Receiver          string            `json:"receiver"`
				NumFiring         int               `json:"numFiring"`
				ExternalURL       string            `json:"externalURL"`
				GroupLabels       map[string]string `json:"groupLabels"`
				NumResolved       int               `json:"numResolved"`
				CommonLabels      map[string]string `json:"commonLabels"`
				TruncatedAlerts   int               `json:"truncatedAlerts"`
				CommonAnnotations map[string]string `json:"commonAnnotations"`
			} `json:"payload"`
		} `json:"last_alert"`
		ResolutionNotes []struct {
			ID        string `json:"id"`
			Author    string `json:"author"`
			CreatedAt string `json:"created_at"`
