// WebhookHandler handles incoming webhook requests from Grafana IRM
type WebhookHandler struct {
	amClient      *alertmanager.Client
	grafanaClient *grafana.Client
	username      string
	password      string
	allowlist     map[string]bool
}

// NewWebhookHandler creates a new webhook handler
func NewWebhookHandler(amClient *alertmanager.Client, grafanaClient *grafana.Client) *WebhookHandler {
	username := os.Getenv("WEBHOOK_USERNAME")
	password := os.Getenv("WEBHOOK_PASSWORD")
	allowlistEnv := os.Getenv("WEBHOOK_EMAIL_ALLOWLIST")

	if username == "" || password == "" {
		log.Fatal("WEBHOOK_USERNAME and WEBHOOK_PASSWORD environment variables must be set")
	}

	allowlist := make(map[string]bool)
	if allowlistEnv != "" {
		emails := strings.Split(allowlistEnv, ",")
		for _, email := range emails {
			allowlist[strings.TrimSpace(email)] = true
		}
	}

	log.Printf("Webhook handler initialized with %d allowed emails", len(allowlist))

	return &WebhookHandler{
		amClient:      amClient,
		grafanaClient: grafanaClient,
		username:      username,
		password:      password,
		allowlist:     allowlist,
	}
}

// basicAuth validates the basic authentication credentials
func (h *WebhookHandler) basicAuth(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		username, password, ok := r.BasicAuth()
		if !ok || username != h.username || password != h.password {
			w.Header().Set("WWW-Authenticate", `Basic realm="Restricted"`)
			http.Error(w, "Unauthorized", http.StatusUnauthorized)
			return
		}
		next(w, r)
	}
}

// HandleWebhook processes incoming webhook events
func (h *WebhookHandler) HandleWebhook(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	ctx := r.Context()

	var event WebhookEvent
	if err := json.NewDecoder(r.Body).Decode(&event); err != nil {
		log.Printf("Failed to decode webhook payload: %v", err)
		http.Error(w, "Invalid payload", http.StatusBadRequest)
		return
	}

	// Ignore if event.type does not exist or is empty
	if event.Event.Type == "" {
		log.Println("Ignoring webhook event: event.type is empty")
		w.WriteHeader(http.StatusOK)
		json.NewEncoder(w).Encode(map[string]string{"status": "ignored", "reason": "no event type"})
		return
	}

	// Only process silence events
	if event.Event.Type != "silence" {
		log.Printf("Ignoring webhook event: type is %s (not silence)", event.Event.Type)
		w.WriteHeader(http.StatusOK)
		json.NewEncoder(w).Encode(map[string]string{"status": "ignored", "reason": "not a silence event"})
		return
	}

	log.Printf("Processing silence event for alert group %s by user %s", event.AlertGroup.ID, event.User.Email)

	// Check if user email is in allowlist
	isAllowed := h.allowlist[event.User.Email]

	if !isAllowed {
		// User NOT in allowlist - unsilence the alert in Grafana
		log.Printf("User %s not in allowlist, unsilencing alert group %s in Grafana", event.User.Email, event.AlertGroup.ID)
		if err := h.grafanaClient.UnsilenceAlertGroup(event.AlertGroup.ID); err != nil {
			log.Printf("Failed to unsilence alert group %s: %v", event.AlertGroup.ID, err)
			http.Error(w, fmt.Sprintf("Failed to unsilence alert: %v", err), http.StatusInternalServerError)
			return
		}
		log.Printf("Successfully unsilenced alert group %s", event.AlertGroup.ID)
		w.WriteHeader(http.StatusOK)
		json.NewEncoder(w).Encode(map[string]string{"status": "unsilenced", "alert_group_id": event.AlertGroup.ID})
		return
	}

	// User IS in allowlist and has event.until - create silence in Alertmanager
	if event.Event.Until == "" {
		log.Printf("User %s in allowlist but no until time specified, ignoring", event.User.Email)
		w.WriteHeader(http.StatusOK)
		json.NewEncoder(w).Encode(map[string]string{"status": "ignored", "reason": "no until time"})
		return
	}

	// Parse until time
	untilTime, err := time.Parse(time.RFC3339, event.Event.Until)
	if err != nil {
		log.Printf("Failed to parse until time %s: %v", event.Event.Until, err)
		http.Error(w, fmt.Sprintf("Invalid until time: %v", err), http.StatusBadRequest)
		return
	}

	// Create silence in Alertmanager for each alert in the group
	silencesCreated := 0
	for _, alert := range event.AlertGroup.LastAlert.Payload.Alerts {
		silenceID, err := h.createSilenceForAlert(ctx, alert, event, untilTime)
		if err != nil {
			log.Printf("Failed to create silence for alert %s: %v", alert.Fingerprint, err)
			// Continue with other alerts
			continue
		}
		log.Printf("Created silence %s for alert %s", silenceID, alert.Fingerprint)
		silencesCreated++
	}

	if silencesCreated == 0 {
		http.Error(w, "Failed to create any silences", http.StatusInternalServerError)
		return
	}

	log.Printf("Successfully created %d silences in Alertmanager for alert group %s", silencesCreated, event.AlertGroup.ID)
	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(map[string]string{
		"status":           "silenced",
		"alert_group_id":   event.AlertGroup.ID,
		"silences_created": fmt.Sprintf("%d", silencesCreated),
	})
}

// createSilenceForAlert creates a silence in Alertmanager for a single alert
func (h *WebhookHandler) createSilenceForAlert(ctx context.Context, alert struct {
	EndsAt       string            `json:"endsAt"`
	Labels       map[string]string `json:"labels"`
	Status       string            `json:"status"`
	StartsAt     string            `json:"startsAt"`
	Annotations  map[string]string `json:"annotations"`
	Fingerprint  string            `json:"fingerprint"`
	GeneratorURL string            `json:"generatorURL"`
}, event WebhookEvent, untilTime time.Time) (string, error) {

	// Build matchers from alert labels
	matchers := make(models.Matchers, 0, len(alert.Labels))
	for key, value := range alert.Labels {
		isEqual := true
		isRegex := false
		name := key
		val := value
		matchers = append(matchers, &models.Matcher{
			IsEqual: &isEqual,
			IsRegex: &isRegex,
			Name:    &name,
			Value:   &val,
		})
	}

	// Create comment with alert group details
	comment := fmt.Sprintf("Automated silence for Grafana IRM Alert Group: %s - %s (ID: %s)",
		event.AlertGroup.Title,
		event.AlertGroup.Permalinks.Web,
		event.AlertGroup.ID,
	)

	// Create silence
	startsAt := strfmt.DateTime(time.Now())
	endsAt := strfmt.DateTime(untilTime)
	createdBy := event.User.Email

	silence := &models.PostableSilence{
		Silence: models.Silence{
			Comment:   &comment,
			CreatedBy: &createdBy,
			Matchers:  matchers,
			StartsAt:  &startsAt,
			EndsAt:    &endsAt,
		},
	}

	log.Printf("Creating silence in Alertmanager for alert %s (fingerprint: %s) until %s",
		alert.Labels["alertname"], alert.Fingerprint, untilTime.Format(time.RFC3339))

	return h.amClient.CreateSilence(ctx, silence)
}

// RegisterRoutes registers the webhook routes
func (h *WebhookHandler) RegisterRoutes(mux *http.ServeMux) {
	mux.HandleFunc("/webhook", h.basicAuth(h.HandleWebhook))
}

package alertmanager

import (
	"context"
	"log"
	"os"
	"sync"

	"github.com/go-openapi/strfmt"
	amclient "github.com/prometheus/alertmanager/api/v2/client"
	"github.com/prometheus/alertmanager/api/v2/client/alert"
	"github.com/prometheus/alertmanager/api/v2/client/silence"
	"github.com/prometheus/alertmanager/api/v2/models"
)

// Client wraps the Alertmanager API client
type Client struct {
	api          *amclient.AlertmanagerAPI
	silenceCache map[string]*models.GettableSilence
	cacheMutex   sync.RWMutex
}

// NewClient creates a new Alertmanager client
// It reads the ALERTMANAGER_HOST environment variable or defaults to localhost:9093
func NewClient() *Client {
	alertmanagerHost := os.Getenv("ALERTMANAGER_HOST")
	if alertmanagerHost == "" {
		alertmanagerHost = "localhost:9093"
	}

	cfg := amclient.DefaultTransportConfig().WithHost(alertmanagerHost)
	api := amclient.NewHTTPClientWithConfig(strfmt.Default, cfg)
	log.Printf("Alertmanager client initialized for host: %s", alertmanagerHost)

	return &Client{
		api:          api,
		silenceCache: make(map[string]*models.GettableSilence),
	}
}

// GetAllAlerts fetches all alerts from Alertmanager, including resolved and silenced
func (c *Client) GetAllAlerts(ctx context.Context) ([]*models.GettableAlert, error) {
	params := alert.NewGetAlertsParams().
		WithContext(ctx)

	ok, err := c.api.Alert.GetAlerts(params)
	if err != nil {
		return nil, err
	}

	return ok.Payload, nil
}

// GetSilence retrieves silence details by silence ID with caching
func (c *Client) GetSilence(ctx context.Context, silenceID string) (*models.GettableSilence, error) {
	if silenceID == "" {
		return nil, nil
	}

	// Check cache first (read lock)
	c.cacheMutex.RLock()
	if silence, exists := c.silenceCache[silenceID]; exists {
		c.cacheMutex.RUnlock()
		return silence, nil
	}
	c.cacheMutex.RUnlock()

	// Silence not in cache, fetch from API
	params := silence.NewGetSilenceParams().
		WithSilenceID(strfmt.UUID(silenceID)).
		WithContext(ctx)

	ok, err := c.api.Silence.GetSilence(params)
	if err != nil {
		log.Printf("Failed to fetch silence %s: %v", silenceID, err)
		return nil, err
	}

	// Store in cache (write lock)
	c.cacheMutex.Lock()
	c.silenceCache[silenceID] = ok.Payload
	c.cacheMutex.Unlock()

	log.Printf("Cached silence %s (author: %s)", silenceID, *ok.Payload.CreatedBy)
	return ok.Payload, nil
}

// GetSilenceAuthor retrieves the author of a silence by silence ID (with caching)
func (c *Client) GetSilenceAuthor(ctx context.Context, silenceID string) string {
	silence, err := c.GetSilence(ctx, silenceID)
	if err != nil || silence == nil {
		return ""
	}
	if silence.CreatedBy != nil {
		return *silence.CreatedBy
	}
	return ""
}

// CreateSilence creates a new silence in Alertmanager
func (c *Client) CreateSilence(ctx context.Context, silenceSpec *models.PostableSilence) (string, error) {
	params := silence.NewPostSilencesParams().
		WithSilence(silenceSpec).
		WithContext(ctx)

	ok, err := c.api.Silence.PostSilences(params)
	if err != nil {
		return "", err
	}

	silenceID := ok.Payload.SilenceID
	log.Printf("Created silence %s (author: %s, comment: %s)", silenceID, *silenceSpec.CreatedBy, *silenceSpec.Comment)
	return silenceID, nil
}

// IsAlertSilenced checks if an alert is currently silenced in Alertmanager
func (c *Client) IsAlertSilenced(alert *models.GettableAlert) bool {
	if alert.Status == nil {
		return false
	}
	return len(alert.Status.SilencedBy) > 0
}

package main

import (
	"context"
	"fmt"
	"log"
	"net/http"
	"os"
	"strconv"
	"time"

	"github.com/gabrielpetry/alertmanager-alert-sync/internal/alertmanager"
	"github.com/gabrielpetry/alertmanager-alert-sync/internal/grafana"
	"github.com/gabrielpetry/alertmanager-alert-sync/internal/metrics"
	"github.com/gabrielpetry/alertmanager-alert-sync/internal/server"
	"github.com/gabrielpetry/alertmanager-alert-sync/internal/sync"
)

func main() {
	log.Println("Starting Alertmanager Alert Sync...")

	// Initialize Alertmanager client
	amClient := alertmanager.NewClient()

	// Initialize Grafana IRM client
	grafanaClient, err := grafana.NewClient()
	if err != nil {
		log.Printf("Warning: Grafana client initialization failed: %v", err)
		log.Println("Reconciliation features will be disabled")
		grafanaClient = nil
	}

	// Initialize metrics exporter
	exporter := metrics.NewExporter()

	// Initialize reconciler (if Grafana client is available)
	var reconciler *sync.Reconciler
	if grafanaClient != nil {
		reconciler = sync.NewReconciler(amClient, grafanaClient, exporter)
	}

	// Initialize server with all dependencies
	srv := server.NewServer(amClient, grafanaClient, exporter, reconciler)

	// Initialize webhook handler if Grafana client is available
	var webhookHandler *server.WebhookHandler
	if grafanaClient != nil {
		webhookHandler = server.NewWebhookHandler(amClient, grafanaClient)
	}

	// Start background reconciliation if enabled
	if reconciler != nil {
		reconcileIntervalStr := os.Getenv("RECONCILE_INTERVAL")
		if reconcileIntervalStr != "" {
			interval, err := strconv.Atoi(reconcileIntervalStr)
			if err != nil || interval <= 0 {
				log.Printf("Invalid RECONCILE_INTERVAL value '%s', must be a positive integer (seconds)", reconcileIntervalStr)
			} else {
				// Use optimized reconciliation that handles both sync and metrics export
				go startOptimizedReconciliationLoop(reconciler, time.Duration(interval)*time.Second)
				log.Printf("Optimized background reconciliation enabled with interval: %d seconds", interval)
				log.Println("This includes both alert metrics export and silence synchronization")
			}
		} else {
			log.Println("Background reconciliation disabled (set RECONCILE_INTERVAL to enable)")
		}
	} else {
		log.Println("Grafana IRM integration disabled - no background processing available")
	}

	// Register HTTP handlers
	mux := http.NewServeMux()
	mux.HandleFunc("/metrics", srv.MetricsHandler)
	mux.HandleFunc("/healthz", srv.HealthzHandler)
	mux.HandleFunc("/readyz", srv.ReadyzHandler)

	// Only register webhook endpoints if Grafana client is available
	if grafanaClient != nil {
		if webhookHandler != nil {
			webhookHandler.RegisterRoutes(mux)
			log.Println("Webhook endpoint enabled at /webhook (requires basic auth)")
		}
		log.Println("Grafana IRM integration enabled")
	} else {
		log.Println("Grafana IRM integration disabled")
	}

	// Get port from environment or use default
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	// Start the server
	log.Printf("Server listening on port :%s", port)
	log.Printf("Endpoints:")
	log.Printf("  - /metrics: Prometheus metrics for reconciliation")
	log.Printf("  - /healthz: Liveness probe")
	log.Printf("  - /readyz: Readiness probe")
	if grafanaClient != nil {
		if webhookHandler != nil {
			log.Printf("  - /webhook: Grafana IRM webhook endpoint (POST, basic auth required)")
		}
	}

	if err := http.ListenAndServe(fmt.Sprintf(":%s", port), mux); err != nil {
		log.Fatal(err)
	}
}

// startOptimizedReconciliationLoop runs the optimized reconciliation process at regular intervals
// This handles both metrics export and silence synchronization in parallel
func startOptimizedReconciliationLoop(reconciler *sync.Reconciler, interval time.Duration) {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	log.Printf("Starting optimized reconciliation loop with interval: %v", interval)

	// Run immediately on startup
	runOptimizedReconciliation(reconciler)

	// Then run on interval
	for range ticker.C {
		runOptimizedReconciliation(reconciler)
	}
}

// runOptimizedReconciliation performs a single optimized reconciliation cycle with error handling
func runOptimizedReconciliation(reconciler *sync.Reconciler) {
	ctx := context.Background()
	log.Println("Running scheduled optimized reconciliation...")

	if err := reconciler.ReconcileAndResolveOptimized(ctx); err != nil {
		log.Printf("Optimized reconciliation failed: %v", err)
	} else {
		log.Println("Optimized reconciliation completed successfully")
	}
}

package metrics

import (
	"context"
	"fmt"
	"log"
	"os"
	"strings"
	"time"

	"github.com/gabrielpetry/alertmanager-alert-sync/internal/alertmanager"
	"github.com/gabrielpetry/alertmanager-alert-sync/internal/grafana"
	"github.com/prometheus/alertmanager/api/v2/models"
	"github.com/prometheus/client_golang/prometheus"
	"github.com/prometheus/client_golang/prometheus/promauto"
)

// Exporter handles Prometheus metrics for alert reconciliation
type Exporter struct {
	// Reconciliation metrics
	reconciliationTotal          prometheus.Counter
	reconciliationFailuresTotal  prometheus.Counter
	reconciliationDuration       prometheus.Histogram
	inconsistenciesFound         prometheus.Gauge
	inconsistenciesResolved      prometheus.Counter
	inconsistenciesFailedResolve prometheus.Counter
	lastReconciliationTime       prometheus.Gauge
	lastReconciliationSuccess    prometheus.Gauge

	// Alert state metrics
	alertStateGauge          *prometheus.GaugeVec
	alertExportTotal         prometheus.Counter
	alertExportFailuresTotal prometheus.Counter
	lastAlertExportTime      prometheus.Gauge

	// Configuration for alert labels
	alertLabels      []string
	alertAnnotations []string
}

// NewExporter creates and initializes a new metrics exporter for reconciliation
func NewExporter() *Exporter {
	log.Println("Initializing reconciliation metrics...")

	reconciliationTotal := promauto.NewCounter(
		prometheus.CounterOpts{
			Name: "alertmanager_sync_reconciliation_total",
			Help: "Total number of reconciliation attempts",
		},
	)

	reconciliationFailuresTotal := promauto.NewCounter(
		prometheus.CounterOpts{
			Name: "alertmanager_sync_reconciliation_failures_total",
			Help: "Total number of failed reconciliation attempts",
		},
	)

	reconciliationDuration := promauto.NewHistogram(
		prometheus.HistogramOpts{
			Name:    "alertmanager_sync_reconciliation_duration_seconds",
			Help:    "Duration of reconciliation operations in seconds",
			Buckets: prometheus.DefBuckets,
		},
	)

	inconsistenciesFound := promauto.NewGauge(
		prometheus.GaugeOpts{
			Name: "alertmanager_sync_inconsistencies_found",
			Help: "Number of inconsistencies found in last reconciliation",
		},
	)

	inconsistenciesResolved := promauto.NewCounter(
		prometheus.CounterOpts{
			Name: "alertmanager_sync_inconsistencies_resolved_total",
			Help: "Total number of inconsistencies successfully resolved",
		},
	)

	inconsistenciesFailedResolve := promauto.NewCounter(
		prometheus.CounterOpts{
			Name: "alertmanager_sync_inconsistencies_failed_resolve_total",
			Help: "Total number of inconsistencies that failed to resolve",
		},
	)

	lastReconciliationTime := promauto.NewGauge(
		prometheus.GaugeOpts{
			Name: "alertmanager_sync_last_reconciliation_timestamp_seconds",
			Help: "Timestamp of the last reconciliation attempt (Unix time)",
		},
	)

	lastReconciliationSuccess := promauto.NewGauge(
		prometheus.GaugeOpts{
			Name: "alertmanager_sync_last_reconciliation_success",
			Help: "Whether the last reconciliation was successful (1=success, 0=failure)",
		},
	)

	// Parse alert labels and annotations from environment
	alertLabels := parseEnvList("ALERTMANAGER_ALERTS_LABELS")
	alertAnnotations := parseEnvList("ALERTMANAGER_ALERTS_ANNOTATIONS")

	// Default labels that are always included
	defaultLabels := []string{"alertname", "fingerprint", "suppressed", "acknowledged_by", "resolved_by", "silenced_by", "inhibited_by", "alert_group_id", "acknowledged_at", "created_at", "resolved_at"}

	// Combine all labels for the metric
	allLabels := append(defaultLabels, alertLabels...)
	allLabels = append(allLabels, alertAnnotations...)

	log.Printf("Alert export configuration:")
	log.Printf("  - Alert labels to export: %v", alertLabels)
	log.Printf("  - Alert annotations to export: %v", alertAnnotations)
	log.Printf("  - All metric labels: %v", allLabels)

	// Create alert state gauge
	alertStateGauge := promauto.NewGaugeVec(
		prometheus.GaugeOpts{
			Name: "alertmanager_sync_alert_state",
			Help: "Current state of alerts from Alertmanager (1=active, value indicates if suppressed)",
		},
		allLabels,
	)

	alertExportTotal := promauto.NewCounter(
		prometheus.CounterOpts{
			Name: "alertmanager_sync_alert_export_total",
			Help: "Total number of alert export attempts",
		},
	)

	alertExportFailuresTotal := promauto.NewCounter(
		prometheus.CounterOpts{
			Name: "alertmanager_sync_alert_export_failures_total",
			Help: "Total number of failed alert export attempts",
		},
	)

	lastAlertExportTime := promauto.NewGauge(
		prometheus.GaugeOpts{
			Name: "alertmanager_sync_last_alert_export_timestamp_seconds",
			Help: "Timestamp of the last alert export (Unix time)",
		},
	)

	return &Exporter{
		reconciliationTotal:          reconciliationTotal,
		reconciliationFailuresTotal:  reconciliationFailuresTotal,
		reconciliationDuration:       reconciliationDuration,
		inconsistenciesFound:         inconsistenciesFound,
		inconsistenciesResolved:      inconsistenciesResolved,
		inconsistenciesFailedResolve: inconsistenciesFailedResolve,
		lastReconciliationTime:       lastReconciliationTime,
		lastReconciliationSuccess:    lastReconciliationSuccess,
		alertStateGauge:              alertStateGauge,
		alertExportTotal:             alertExportTotal,
		alertExportFailuresTotal:     alertExportFailuresTotal,
		lastAlertExportTime:          lastAlertExportTime,
		alertLabels:                  alertLabels,
		alertAnnotations:             alertAnnotations,
	}
}

// parseEnvList parses a comma-separated environment variable into a list of trimmed strings
func parseEnvList(envVar string) []string {
	value := os.Getenv(envVar)
	if value == "" {
		return []string{}
	}

	parts := strings.Split(value, ",")
	result := make([]string, 0, len(parts))

	for _, part := range parts {
		trimmed := strings.TrimSpace(part)
		if trimmed != "" {
			result = append(result, trimmed)
		}
	}

	return result
}

// RecordReconciliationStart records the start of a reconciliation cycle
func (e *Exporter) RecordReconciliationStart() func() {
	e.reconciliationTotal.Inc()
	e.lastReconciliationTime.SetToCurrentTime()

	startTime := time.Now()

	// Return a function to be called when reconciliation completes
	return func() {
		duration := time.Since(startTime).Seconds()
		e.reconciliationDuration.Observe(duration)
	}
}

// RecordReconciliationSuccess records a successful reconciliation
func (e *Exporter) RecordReconciliationSuccess(inconsistenciesFound, inconsistenciesResolved int) {
	e.lastReconciliationSuccess.Set(1)
	e.inconsistenciesFound.Set(float64(inconsistenciesFound))
	e.inconsistenciesResolved.Add(float64(inconsistenciesResolved))
}

// RecordReconciliationFailure records a failed reconciliation
func (e *Exporter) RecordReconciliationFailure() {
	e.reconciliationFailuresTotal.Inc()
	e.lastReconciliationSuccess.Set(0)
}

// RecordInconsistencyResolved records a successfully resolved inconsistency
func (e *Exporter) RecordInconsistencyResolved() {
	e.inconsistenciesResolved.Inc()
}

// RecordInconsistencyFailedResolve records a failed inconsistency resolution
func (e *Exporter) RecordInconsistencyFailedResolve() {
	e.inconsistenciesFailedResolve.Inc()
}

// ExportAlertsWithGrafana exports alerts with additional information from Grafana IRM
func (e *Exporter) ExportAlertsWithGrafana(ctx context.Context, alerts []*models.GettableAlert, grafanaAlertGroups []grafana.AlertGroup, grafanaClient *grafana.Client, amClient *alertmanager.Client) error {
	e.alertExportTotal.Inc()
	e.lastAlertExportTime.SetToCurrentTime()

	// Reset previous metrics to avoid stale data
	e.alertStateGauge.Reset()

	for _, alert := range alerts {
		var grafanaGroup *grafana.AlertGroup

		// Find the matching Grafana alert group by searching through all groups
		if alert.Fingerprint != nil {
			alertFingerprint := *alert.Fingerprint
			for i := range grafanaAlertGroups {
				group := &grafanaAlertGroups[i]
				// Check if this alert's fingerprint exists in this group
				for _, gAlert := range group.LastAlert.Payload.Alerts {
					if gAlert.Fingerprint == alertFingerprint {
						grafanaGroup = group
						break
					}
				}
				if grafanaGroup != nil {
					break
				}
			}
		}

		if err := e.exportAlert(ctx, alert, grafanaGroup, grafanaClient, amClient); err != nil {
			log.Printf("Error exporting alert %s: %v", alert.Labels["alertname"], err)
			// Continue with other alerts even if one fails
		}
	}

	return nil
}

// exportAlert exports a single alert as a Prometheus metric
func (e *Exporter) exportAlert(ctx context.Context, alert *models.GettableAlert, grafanaGroup *grafana.AlertGroup, grafanaClient *grafana.Client, amClient *alertmanager.Client) error {
	// Extract alert fingerprint
	fingerprint := ""
	if alert.Fingerprint != nil {
		fingerprint = *alert.Fingerprint
	}

	// Determine if alert is suppressed (silenced)
	suppressed := "false"
	silencedBy := ""

	if len(alert.Status.SilencedBy) > 0 {
		suppressed = "true"

		// Get the author of the first silence (with caching)
		if amClient != nil {
			silencedBy = amClient.GetSilenceAuthor(ctx, alert.Status.SilencedBy[0])
		}
	}

	// Extract inhibited_by (fingerprint of inhibiting alert)
	inhibitedBy := ""
	if len(alert.Status.InhibitedBy) > 0 {
		// Use the first inhibiting alert's fingerprint
		inhibitedBy = alert.Status.InhibitedBy[0]
	}

	// Extract acknowledged_by, resolved_by, alert_group_id and timestamps from Grafana
	acknowledgedBy := ""
	resolvedBy := ""
	alertGroupID := ""
	acknowledgedAt := ""
	createdAt := ""
	resolvedAt := ""

	if grafanaGroup != nil {
		alertGroupID = grafanaGroup.ID

		// Format timestamps as Unix timestamps (seconds since epoch, empty if not valid)
		if grafanaGroup.AcknowledgedAt.Valid {
			acknowledgedAt = fmt.Sprintf("%d", grafanaGroup.AcknowledgedAt.Time.Unix())
		}
		if grafanaGroup.CreatedAt.Valid {
			createdAt = fmt.Sprintf("%d", grafanaGroup.CreatedAt.Time.Unix())
		}
		if grafanaGroup.ResolvedAt.Valid {
			resolvedAt = fmt.Sprintf("%d", grafanaGroup.ResolvedAt.Time.Unix())
		}

		if grafanaClient != nil {
			// Fetch user emails from user IDs (with caching)
			if grafanaGroup.AcknowledgedBy != "" {
				acknowledgedBy = grafanaClient.GetUserEmail(grafanaGroup.AcknowledgedBy)
			}
			if grafanaGroup.ResolvedBy != "" {
				resolvedBy = grafanaClient.GetUserEmail(grafanaGroup.ResolvedBy)
			}
		}
	}

	// Build metric labels
	metricLabels := prometheus.Labels{
		"alertname":       alert.Labels["alertname"],
		"fingerprint":     fingerprint,
		"suppressed":      suppressed,
		"acknowledged_by": acknowledgedBy,
		"resolved_by":     resolvedBy,
		"silenced_by":     silencedBy,
		"inhibited_by":    inhibitedBy,
		"alert_group_id":  alertGroupID,
		"acknowledged_at": acknowledgedAt,
		"created_at":      createdAt,
		"resolved_at":     resolvedAt,
	}

	// Add extra labels from alert labels
	for _, label := range e.alertLabels {
		if val, ok := alert.Labels[label]; ok {
			metricLabels[label] = val
		} else {
			metricLabels[label] = ""
		}
	}

	// Add extra labels from alert annotations
	for _, annotation := range e.alertAnnotations {
		if val, ok := alert.Annotations[annotation]; ok {
			metricLabels[annotation] = val
		} else {
			metricLabels[annotation] = ""
		}
	}
	var alertStateNumber float64
	alertStateNumber = 0.0
	// Set the gauge value to 1 (alert firing)
	if *alert.Status.State == "active" {
		alertStateNumber = 1
	}
	// Set the gauge value to 1 (alert exists)
	e.alertStateGauge.With(metricLabels).Set(alertStateNumber)

	return nil
}

// RecordAlertExportFailure increments the alert export failure counter
func (e *Exporter) RecordAlertExportFailure() {
	e.alertExportFailuresTotal.Inc()
}
